package net.wchbdotnet.arcaneward;

import java.util.Arrays;
import java.util.IdentityHashMap;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

final class ArcaneFortifiedModels
{
	private static final int INVENTORY_MODEL = 11310;
	private static final int MALE_MODEL = 11050;
	private static final int FEMALE_MODEL = 35756;
	private static final short PALE_SIGIL = 127;
	private static final short FORTIFIED_GOLD = JagexColor.packHSL(7, 7, 86);
	private static final short CRIMSON_DARK = JagexColor.packHSL(0, 7, 24);
	private static final short CRIMSON_MID = JagexColor.packHSL(0, 7, 34);
	private static final short CRIMSON_BASE = JagexColor.packHSL(0, 7, 44);
	private static final short CRIMSON_BRIGHT = JagexColor.packHSL(1, 7, 52);
	private static final short TURQUOISE_DARK = JagexColor.packHSL(31, 6, 25);
	private static final short TURQUOISE_MID = JagexColor.packHSL(31, 7, 38);
	private static final short TURQUOISE_BASE = JagexColor.packHSL(31, 7, 49);
	private static final short TURQUOISE_BRIGHT = JagexColor.packHSL(30, 7, 60);

	private final Client client;
	private short[] maleOriginal;
	private short[] maleOr;
	private short[] maleF;
	private short[] femaleOriginal;
	private short[] femaleOr;
	private short[] femaleF;
	private short[] inventoryOriginal;
	private short[] inventoryOr;
	private short[] inventoryF;
	private LitColors maleLitOriginal;
	private LitColors maleLitOr;
	private LitColors maleLitF;
	private LitColors femaleLitOriginal;
	private LitColors femaleLitOr;
	private LitColors femaleLitF;
	private int[] equippedFaces1;
	private int[] equippedFaces2;
	private int[] equippedFaces3;
	private int equippedVertexCount;
	private final IdentityHashMap<Model, Integer> equippedTopologyStarts = new IdentityHashMap<>();

	ArcaneFortifiedModels(Client client)
	{
		this.client = client;
	}

	void load()
	{
		equippedTopologyStarts.clear();

		ModelData inventorySource = client.loadModelData(INVENTORY_MODEL);
		inventoryOriginal = inventorySource.getFaceColors().clone();
		inventoryOr = paintedColors(inventoryOriginal, ShieldAppearance.ARCANE_OR);
		inventoryF = paintedColors(inventoryOriginal, ShieldAppearance.ARCANE_F);

		ModelData maleSource = client.loadModelData(MALE_MODEL);
		equippedFaces1 = maleSource.getFaceIndices1().clone();
		equippedFaces2 = maleSource.getFaceIndices2().clone();
		equippedFaces3 = maleSource.getFaceIndices3().clone();
		equippedVertexCount = maleSource.getVerticesCount();
		maleOriginal = maleSource.getFaceColors().clone();
		maleOr = paintedColors(maleOriginal, ShieldAppearance.ARCANE_OR);
		maleF = paintedColors(maleOriginal, ShieldAppearance.ARCANE_F);
		maleLitOriginal = new LitColors(maleSource.light(64, 850, -30, -50, -30));
		maleLitOr = new LitColors(coloredClone(maleSource, maleOr).light(64, 850, -30, -50, -30));
		maleLitF = new LitColors(coloredClone(maleSource, maleF).light(64, 850, -30, -50, -30));

		ModelData femaleSource = client.loadModelData(FEMALE_MODEL);
		femaleOriginal = femaleSource.getFaceColors().clone();
		femaleOr = paintedColors(femaleOriginal, ShieldAppearance.ARCANE_OR);
		femaleF = paintedColors(femaleOriginal, ShieldAppearance.ARCANE_F);
		femaleLitOriginal = new LitColors(femaleSource.light(64, 850, -30, -50, -30));
		femaleLitOr = new LitColors(coloredClone(femaleSource, femaleOr).light(64, 850, -30, -50, -30));
		femaleLitF = new LitColors(coloredClone(femaleSource, femaleF).light(64, 850, -30, -50, -30));
	}

	short[] inventoryColorsToReplace()
	{
		return inventoryOriginal.clone();
	}

	short[] inventoryReplacementColors(ShieldAppearance appearance)
	{
		return (appearance == ShieldAppearance.ARCANE_F ? inventoryF : inventoryOr).clone();
	}

	boolean paintPlayerModel(Model model, ShieldAppearance appearance)
	{
		if (model == null || !appearance.isRecoloredArcane())
		{
			return false;
		}
		short[] maleTarget = appearance == ShieldAppearance.ARCANE_F ? maleF : maleOr;
		short[] femaleTarget = appearance == ShieldAppearance.ARCANE_F ? femaleF : femaleOr;
		LitColors maleLitTarget = appearance == ShieldAppearance.ARCANE_F ? maleLitF : maleLitOr;
		LitColors femaleLitTarget = appearance == ShieldAppearance.ARCANE_F ? femaleLitF : femaleLitOr;
		Integer cachedStart = equippedTopologyStarts.get(model);
		int topologyStart = cachedStart == null
			? findTopology(model, equippedFaces1, equippedFaces2, equippedFaces3, equippedVertexCount)
			: cachedStart;
		if (topologyStart >= 0)
		{
			short[] target = model.getFaceCount() >= maleTarget.length ? maleTarget : femaleTarget;
			LitColors litTarget = target == maleTarget ? maleLitTarget : femaleLitTarget;
			applyRawAt(model, target, topologyStart);
			applyLitAt(model, litTarget, topologyStart);
			equippedTopologyStarts.put(model, topologyStart);
			return true;
		}
		short[] unlit = model.getUnlitFaceColors();
		if (unlit != null)
		{
			int start = replaceAnySequenceAt(unlit, maleTarget, maleOriginal, maleOr, maleF);
			if (start >= 0)
			{
				applyLitAt(model, maleLitTarget, start);
				return true;
			}
			start = replaceAnySequenceAt(unlit, femaleTarget, femaleOriginal, femaleOr, femaleF);
			if (start >= 0)
			{
				applyLitAt(model, femaleLitTarget, start);
				return true;
			}
		}
		return replaceAnyLitSequence(model, maleLitTarget, maleLitOriginal, maleLitOr, maleLitF)
			|| replaceAnyLitSequence(model, femaleLitTarget, femaleLitOriginal, femaleLitOr, femaleLitF);
	}

	private static short[] paintedColors(short[] source, ShieldAppearance appearance)
	{
		short[] colors = source.clone();
		for (int face = 0; face < colors.length; ++face)
		{
			colors[face] = colors[face] == PALE_SIGIL
				? FORTIFIED_GOLD
				: bodyColor(colors[face], appearance);
		}
		return colors;
	}

	private static ModelData coloredClone(ModelData source, short[] colors)
	{
		ModelData result = source.cloneColors();
		System.arraycopy(colors, 0, result.getFaceColors(), 0, colors.length);
		return result;
	}

	private static short bodyColor(short original, ShieldAppearance appearance)
	{
		boolean turquoise = appearance == ShieldAppearance.ARCANE_F;
		switch (original & 0xffff)
		{
			case 5594:
			case 7056:
				return turquoise ? TURQUOISE_DARK : CRIMSON_DARK;
			case 7079:
			case 7089:
				return turquoise ? TURQUOISE_MID : CRIMSON_MID;
			case 7104:
				return turquoise ? TURQUOISE_BRIGHT : CRIMSON_BRIGHT;
			default:
				return turquoise ? TURQUOISE_BASE : CRIMSON_BASE;
		}
	}

	private static int replaceAnySequenceAt(short[] target, short[] replacement, short[]... candidates)
	{
		for (short[] candidate : candidates)
		{
			int start = replaceSequenceAt(target, candidate, replacement);
			if (start >= 0)
			{
				return start;
			}
		}
		return -1;
	}

	private static int replaceSequenceAt(short[] target, short[] find, short[] replacement)
	{
		if (find == null || target.length < find.length)
		{
			return -1;
		}
		outer:
		for (int start = 0; start <= target.length - find.length; ++start)
		{
			for (int offset = 0; offset < find.length; ++offset)
			{
				if (target[start + offset] != find[offset])
				{
					continue outer;
				}
			}
			System.arraycopy(replacement, 0, target, start, replacement.length);
			return start;
		}
		return -1;
	}

	private static void applyLitAt(Model target, LitColors replacement, int start)
	{
		int[] first = target.getFaceColors1();
		int[] second = target.getFaceColors2();
		int[] third = target.getFaceColors3();
		if (first == null || start + replacement.first.length > first.length)
		{
			return;
		}
		System.arraycopy(replacement.first, 0, first, start, replacement.first.length);
		System.arraycopy(replacement.second, 0, second, start, replacement.second.length);
		System.arraycopy(replacement.third, 0, third, start, replacement.third.length);
	}

	private static void applyRawAt(Model target, short[] replacement, int start)
	{
		short[] colors = target.getUnlitFaceColors();
		if (colors != null && start + replacement.length <= colors.length)
		{
			System.arraycopy(replacement, 0, colors, start, replacement.length);
		}
	}

	private static int findTopology(Model target, int[] source1, int[] source2,
		int[] source3, int sourceVertexCount)
	{
		int[] target1 = target.getFaceIndices1();
		int[] target2 = target.getFaceIndices2();
		int[] target3 = target.getFaceIndices3();
		if (target1 == null || target1.length < source1.length)
		{
			return -1;
		}
		int[] vertexMap = new int[sourceVertexCount];
		for (int start = 0; start <= target1.length - source1.length; ++start)
		{
			Arrays.fill(vertexMap, -1);
			boolean matches = true;
			for (int face = 0; face < source1.length; ++face)
			{
				if (!mapsVertex(vertexMap, source1[face], target1[start + face])
					|| !mapsVertex(vertexMap, source2[face], target2[start + face])
					|| !mapsVertex(vertexMap, source3[face], target3[start + face]))
				{
					matches = false;
					break;
				}
			}
			if (matches)
			{
				return start;
			}
		}
		return -1;
	}

	private static boolean mapsVertex(int[] vertexMap, int source, int target)
	{
		if (vertexMap[source] == -1)
		{
			vertexMap[source] = target;
			return true;
		}
		return vertexMap[source] == target;
	}

	private static boolean replaceAnyLitSequence(Model target, LitColors replacement, LitColors... candidates)
	{
		for (LitColors candidate : candidates)
		{
			if (replaceLitSequence(target, candidate, replacement))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean replaceLitSequence(Model target, LitColors find, LitColors replacement)
	{
		int[] target1 = target.getFaceColors1();
		int[] target2 = target.getFaceColors2();
		int[] target3 = target.getFaceColors3();
		if (target1 == null || target1.length < find.first.length)
		{
			return false;
		}
		outer:
		for (int start = 0; start <= target1.length - find.first.length; ++start)
		{
			for (int offset = 0; offset < find.first.length; ++offset)
			{
				if (target1[start + offset] != find.first[offset]
					|| target2[start + offset] != find.second[offset]
					|| target3[start + offset] != find.third[offset])
				{
					continue outer;
				}
			}
			System.arraycopy(replacement.first, 0, target1, start, replacement.first.length);
			System.arraycopy(replacement.second, 0, target2, start, replacement.second.length);
			System.arraycopy(replacement.third, 0, target3, start, replacement.third.length);
			return true;
		}
		return false;
	}

	private static final class LitColors
	{
		private final int[] first;
		private final int[] second;
		private final int[] third;

		private LitColors(Model model)
		{
			first = model.getFaceColors1().clone();
			second = model.getFaceColors2().clone();
			third = model.getFaceColors3().clone();
		}
	}
}

package net.wchbdotnet.arcaneward;

final class ArcaneFortifiedPalette
{
	// Face colours present in the vanilla Arcane equipment models (11050/35756).
	private static final short PALE_SIGIL = 127;
	private static final short RECESSED_BRONZE = 7056;
	private static final short BRONZE_PANEL = 7089;
	private static final short BRONZE_FIELD = 7101;

	// The inventory/ground model (11310) has one additional recessed shade.
	private static final short RECESSED_BRONZE_MID = 7079;

	private ArcaneFortifiedPalette()
	{
	}

	static short[] equippedFind()
	{
		return new short[]{PALE_SIGIL, RECESSED_BRONZE, BRONZE_PANEL, BRONZE_FIELD};
	}

	static short[] equippedOriginal()
	{
		return new short[]{PALE_SIGIL, RECESSED_BRONZE, BRONZE_PANEL, BRONZE_FIELD};
	}

	static short[] inventoryFind()
	{
		return new short[]{PALE_SIGIL, RECESSED_BRONZE, RECESSED_BRONZE_MID, 7101};
	}

}

package net.wchbdotnet.arcaneward;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ArcaneWardConfig.GROUP)
public interface ArcaneWardConfig extends Config
{
	String GROUP = "arcaneWard";

	@ConfigItem(
		keyName = "appearance",
		name = "Appearance",
		description = "Choose how Elidinis' ward (f) and (or) appear on your client"
	)
	default ShieldAppearance shieldAppearance()
	{
		return ShieldAppearance.ARCANE_F;
	}
}

package net.wchbdotnet.arcaneward;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.SpritePixels;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PlayerChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.kit.KitType;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import static net.runelite.api.Constants.CLIENT_DEFAULT_ZOOM;

@PluginDescriptor(
	name = "Arcane Ward",
	description = "Changes the local appearance of Elidinis' ward (f) and (or)",
	tags = {"elidinis", "ward", "arcane", "shield", "cosmetic"}
)
public final class ArcaneWardPlugin extends Plugin
{
	static final int ELIDINIS_WARD_F = ItemID.ELIDINIS_WARD_FORTIFIED;
	static final int ELIDINIS_WARD_OR = ItemID.ELIDINIS_WARD_ORNAMENT;
	static final int ARCANE_SPIRIT_SHIELD = ItemID.ARCANE;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ArcaneWardConfig config;
	@Inject private ConfigManager configManager;
	@Inject private OverlayManager overlayManager;
	@Inject private InventoryIconOverlay inventoryIconOverlay;

	private ItemAppearanceSnapshot fortifiedWardSnapshot;
	private ItemAppearanceSnapshot ornamentWardSnapshot;
	private ItemAppearanceSnapshot arcaneSnapshot;
	private boolean localShieldSubstituted;
	private boolean changingComposition;
	private int appliedVisualEquipmentId = -1;
	private BufferedImage originalFortifiedWardIcon;
	private BufferedImage originalOrnamentWardIcon;
	private ArcaneFortifiedModels fortifiedModels;

	@Override
	protected void startUp()
	{
		fortifiedModels = new ArcaneFortifiedModels(client);
		overlayManager.add(inventoryIconOverlay);
		clientThread.invokeLater(this::refresh);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(inventoryIconOverlay);
		clientThread.invokeLater(this::restoreEverything);
	}

	@Provides
	ArcaneWardConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ArcaneWardConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ArcaneWardConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(this::refresh);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::refresh);
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			fortifiedWardSnapshot = null;
			ornamentWardSnapshot = null;
			arcaneSnapshot = null;
			localShieldSubstituted = false;
			appliedVisualEquipmentId = -1;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			clientThread.invokeLater(this::applyEquippedAppearance);
		}
	}

	@Subscribe
	public void onPlayerChanged(PlayerChanged event)
	{
		if (!changingComposition && event.getPlayer() == client.getLocalPlayer())
		{
			clientThread.invokeLater(this::applyEquippedAppearance);
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		ShieldAppearance appearance = config.shieldAppearance();
		if (appearance.isRecoloredArcane() && localShieldSubstituted)
		{
			if (!isSupportedWard(getEquippedShieldId()))
			{
				clearSubstitutionFromActualEquipment();
				return;
			}
			Player player = client.getLocalPlayer();
			if (player != null && player.getPlayerComposition() != null)
			{
				int shieldIndex = KitType.SHIELD.getIndex();
				int[] equipment = player.getPlayerComposition().getEquipmentIds();
				if (equipment[shieldIndex] == appliedVisualEquipmentId)
				{
					fortifiedModels.paintPlayerModel(player.getModel(), appearance);
				}
			}
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return;
		}

		Item shield = equipment.getItem(KitType.SHIELD.getIndex());
		if (shield == null || !isSupportedWard(shield.getId()))
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		for (int index = entries.length - 1; index >= 0; --index)
		{
			MenuEntry sourceEntry = entries[index];
			Widget widget = sourceEntry.getWidget();
			if (widget == null
				|| WidgetUtil.componentToInterface(widget.getId()) != InterfaceID.WORNITEMS
				|| !"Examine".equals(sourceEntry.getOption()))
			{
				continue;
			}

			Widget itemWidget = widget.getChild(1);
			if (itemWidget == null || !isSupportedWard(itemWidget.getItemId()))
			{
				continue;
			}

			ShieldAppearance next = config.shieldAppearance().next();
			client.getMenu().createMenuEntry(index)
				.setOption("Use " + next + " appearance")
				.setTarget(sourceEntry.getTarget())
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> configManager.setConfiguration(
					ArcaneWardConfig.GROUP,
					"appearance",
					next.name()));
			return;
		}
	}

	private void refresh()
	{
		restoreEverything();
		fortifiedModels.load();
		captureOriginalIcons();
		if (config.shieldAppearance().usesArcaneModel())
		{
			applyInventoryAndGroundAppearance(ELIDINIS_WARD_F);
			applyInventoryAndGroundAppearance(ELIDINIS_WARD_OR);
		}
		createReplacementIcon();
		applyEquippedAppearance();
	}

	private void captureOriginalIcons()
	{
		client.getItemModelCache().reset();
		client.getItemSpriteCache().reset();
		SpritePixels fortifiedSprite = client.createItemSprite(ELIDINIS_WARD_F, 1, 1,
			SpritePixels.DEFAULT_SHADOW_COLOR, ItemQuantityMode.NEVER, false, CLIENT_DEFAULT_ZOOM);
		SpritePixels ornamentSprite = client.createItemSprite(ELIDINIS_WARD_OR, 1, 1,
			SpritePixels.DEFAULT_SHADOW_COLOR, ItemQuantityMode.NEVER, false, CLIENT_DEFAULT_ZOOM);
		originalFortifiedWardIcon = fortifiedSprite == null ? null : fortifiedSprite.toBufferedImage();
		originalOrnamentWardIcon = ornamentSprite == null ? null : ornamentSprite.toBufferedImage();
		inventoryIconOverlay.setNativeImages(originalFortifiedWardIcon, originalOrnamentWardIcon);
	}

	private void createReplacementIcon()
	{
		if (!config.shieldAppearance().usesArcaneModel())
		{
			inventoryIconOverlay.setReplacementImage(null);
			return;
		}
		client.getItemModelCache().reset();
		client.getItemSpriteCache().reset();
		SpritePixels fortifiedSprite = client.createItemSprite(ELIDINIS_WARD_F, 1, 1,
			SpritePixels.DEFAULT_SHADOW_COLOR, ItemQuantityMode.NEVER, false, CLIENT_DEFAULT_ZOOM);
		SpritePixels ornamentSprite = client.createItemSprite(ELIDINIS_WARD_OR, 1, 1,
			SpritePixels.DEFAULT_SHADOW_COLOR, ItemQuantityMode.NEVER, false, CLIENT_DEFAULT_ZOOM);
		inventoryIconOverlay.setReplacementImages(
			fortifiedSprite == null ? null : fortifiedSprite.toBufferedImage(),
			ornamentSprite == null ? null : ornamentSprite.toBufferedImage());
	}

	private void applyInventoryAndGroundAppearance(int wardId)
	{
		ShieldAppearance appearance = config.shieldAppearance();
		ItemComposition ward = client.getItemDefinition(wardId);
		ItemComposition arcane = client.getItemDefinition(ARCANE_SPIRIT_SHIELD);
		if (wardId == ELIDINIS_WARD_F && fortifiedWardSnapshot == null)
		{
			fortifiedWardSnapshot = new ItemAppearanceSnapshot(ward);
		}
		else if (wardId == ELIDINIS_WARD_OR && ornamentWardSnapshot == null)
		{
			ornamentWardSnapshot = new ItemAppearanceSnapshot(ward);
		}

		ward.setInventoryModel(arcane.getInventoryModel());
		if (appearance.isRecoloredArcane())
		{
			ward.setColorToReplace(fortifiedModels.inventoryColorsToReplace());
			ward.setColorToReplaceWith(fortifiedModels.inventoryReplacementColors(appearance));
		}
		else
		{
			ward.setColorToReplace(clone(arcane.getColorToReplace()));
			ward.setColorToReplaceWith(clone(arcane.getColorToReplaceWith()));
		}
		ward.setTextureToReplace(clone(arcane.getTextureToReplace()));
		ward.setTextureToReplaceWith(clone(arcane.getTextureToReplaceWith()));
		ward.setXan2d(arcane.getXan2d());
		ward.setYan2d(arcane.getYan2d());
		ward.setZan2d(arcane.getZan2d());
		client.getItemModelCache().reset();
		client.getItemSpriteCache().reset();
	}

	private void applyEquippedAppearance()
	{
		ShieldAppearance appearance = config.shieldAppearance();
		if (!appearance.usesArcaneModel())
		{
			clearSubstitutionFromActualEquipment();
			return;
		}

		int equippedShieldId = getEquippedShieldId();
		if (!isSupportedWard(equippedShieldId))
		{
			clearSubstitutionFromActualEquipment();
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null || player.getPlayerComposition() == null)
		{
			return;
		}

		PlayerComposition composition = player.getPlayerComposition();
		int shieldIndex = KitType.SHIELD.getIndex();
		int[] equipment = composition.getEquipmentIds();
		int current = equipment[shieldIndex];
		if (localShieldSubstituted && current == appliedVisualEquipmentId)
		{
			return;
		}
		localShieldSubstituted = false;
		appliedVisualEquipmentId = -1;
		if (appearance.isRecoloredArcane())
		{
			prepareArcaneEquipmentDefinition();
		}
		int replacement = ARCANE_SPIRIT_SHIELD + PlayerComposition.ITEM_OFFSET;
		changingComposition = true;
		try
		{
			equipment[shieldIndex] = replacement;
			composition.removeColorTextureOverride(KitType.SHIELD);
			composition.setHash();
			localShieldSubstituted = true;
			appliedVisualEquipmentId = replacement;
		}
		finally
		{
			changingComposition = false;
		}
	}

	private void restoreEverything()
	{
		inventoryIconOverlay.setReplacementImage(null);
		restoreEquippedAppearance();
		if (fortifiedWardSnapshot != null)
		{
			fortifiedWardSnapshot.restore();
			fortifiedWardSnapshot = null;
		}
		if (ornamentWardSnapshot != null)
		{
			ornamentWardSnapshot.restore();
			ornamentWardSnapshot = null;
		}
		if (arcaneSnapshot != null)
		{
			arcaneSnapshot.restore();
			arcaneSnapshot = null;
		}
		client.getItemModelCache().reset();
		client.getItemSpriteCache().reset();
	}

	private void prepareArcaneEquipmentDefinition()
	{
		ItemComposition arcane = client.getItemDefinition(ARCANE_SPIRIT_SHIELD);
		if (arcaneSnapshot == null)
		{
			arcaneSnapshot = new ItemAppearanceSnapshot(arcane);
		}
		arcane.setColorToReplace(ArcaneFortifiedPalette.equippedFind());
		arcane.setColorToReplaceWith(ArcaneFortifiedPalette.equippedOriginal());
		client.getItemModelCache().reset();
	}

	private void restoreEquippedAppearance()
	{
		clearSubstitutionFromActualEquipment();
	}

	private void clearSubstitutionFromActualEquipment()
	{
		if (!localShieldSubstituted)
		{
			return;
		}

		Player player = client.getLocalPlayer();
		if (player != null && player.getPlayerComposition() != null)
		{
			PlayerComposition composition = player.getPlayerComposition();
			int shieldIndex = KitType.SHIELD.getIndex();
			int[] equipment = composition.getEquipmentIds();
			if (equipment[shieldIndex] == appliedVisualEquipmentId)
			{
				int actualShieldId = getEquippedShieldId();
				int actualEquipmentId = equipmentIdForShield(actualShieldId);
				changingComposition = true;
				try
				{
					equipment[shieldIndex] = actualEquipmentId;
					composition.removeColorTextureOverride(KitType.SHIELD);
					composition.setHash();
				}
				finally
				{
					changingComposition = false;
				}
			}
		}
		localShieldSubstituted = false;
		appliedVisualEquipmentId = -1;
	}

	private int getEquippedShieldId()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return -1;
		}
		Item shield = equipment.getItem(KitType.SHIELD.getIndex());
		return shield == null ? -1 : shield.getId();
	}

	static boolean isSupportedWard(int itemId)
	{
		return itemId == ELIDINIS_WARD_F || itemId == ELIDINIS_WARD_OR;
	}

	static int equipmentIdForShield(int itemId)
	{
		return itemId < 0 ? 0 : itemId + PlayerComposition.ITEM_OFFSET;
	}

	private static short[] clone(short[] value)
	{
		return value == null ? null : value.clone();
	}
}

package net.wchbdotnet.arcaneward;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.BufferProvider;
import net.runelite.api.Client;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

final class InventoryIconOverlay extends WidgetItemOverlay
{
	private final ArcaneWardConfig config;
	private final Client client;
	private BufferedImage fortifiedReplacementImage;
	private BufferedImage ornamentReplacementImage;
	private BufferedImage originalFortifiedWardImage;
	private BufferedImage originalOrnamentWardImage;

	@Inject
	InventoryIconOverlay(ArcaneWardConfig config, Client client)
	{
		this.config = config;
		this.client = client;
		showOnInventory();
		showOnEquipment();
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
	{
		if (!ArcaneWardPlugin.isSupportedWard(itemId)
			|| !config.shieldAppearance().usesArcaneModel()
			|| replacementImage(itemId) == null)
		{
			return;
		}

		BufferedImage replacementImage = replacementImage(itemId);
		BufferedImage originalWardImage = originalImage(itemId);
		Rectangle bounds = itemWidget.getCanvasBounds();
		eraseUncoveredNativePixels(graphics, bounds, originalWardImage, replacementImage);
		graphics.drawImage(replacementImage, bounds.x, bounds.y, null);
	}

	private void eraseUncoveredNativePixels(Graphics2D graphics, Rectangle bounds,
		BufferedImage original, BufferedImage replacement)
	{
		if (original == null || original.getWidth() != replacement.getWidth()
			|| original.getHeight() != replacement.getHeight())
		{
			return;
		}
		BufferProvider buffer = client.getBufferProvider();
		if (buffer == null || buffer.getPixels() == null)
		{
			return;
		}
		int[] canvasPixels = buffer.getPixels();
		int canvasWidth = buffer.getWidth();
		int canvasHeight = buffer.getHeight();
		for (int y = 0; y < original.getHeight(); ++y)
		{
			int cleanX = findCleanBackgroundX(original, replacement, y);
			int sampleCanvasX = bounds.x + cleanX;
			int canvasY = bounds.y + y;
			if (sampleCanvasX < 0 || sampleCanvasX >= canvasWidth
				|| canvasY < 0 || canvasY >= canvasHeight)
			{
				continue;
			}
			graphics.setColor(new Color(canvasPixels[canvasY * canvasWidth + sampleCanvasX] & 0xffffff));
			for (int x = 0; x < original.getWidth(); ++x)
			{
				if ((original.getRGB(x, y) >>> 24) != 0
					&& (replacement.getRGB(x, y) >>> 24) == 0)
				{
					graphics.fillRect(bounds.x + x, canvasY, 1, 1);
				}
			}
		}
	}

	private static int findCleanBackgroundX(BufferedImage original, BufferedImage replacement, int y)
	{
		for (int x = 0; x < original.getWidth(); ++x)
		{
			if ((original.getRGB(x, y) >>> 24) == 0
				&& (replacement.getRGB(x, y) >>> 24) == 0)
			{
				return x;
			}
		}
		return 0;
	}

	void setReplacementImage(BufferedImage replacementImage)
	{
		fortifiedReplacementImage = replacementImage;
		ornamentReplacementImage = replacementImage;
	}

	void setReplacementImages(BufferedImage fortifiedImage, BufferedImage ornamentImage)
	{
		fortifiedReplacementImage = fortifiedImage;
		ornamentReplacementImage = ornamentImage;
	}

	void setNativeImages(BufferedImage fortifiedImage, BufferedImage ornamentImage)
	{
		originalFortifiedWardImage = fortifiedImage;
		originalOrnamentWardImage = ornamentImage;
	}

	private BufferedImage replacementImage(int itemId)
	{
		return itemId == ArcaneWardPlugin.ELIDINIS_WARD_OR
			? ornamentReplacementImage : fortifiedReplacementImage;
	}

	private BufferedImage originalImage(int itemId)
	{
		return itemId == ArcaneWardPlugin.ELIDINIS_WARD_OR
			? originalOrnamentWardImage : originalFortifiedWardImage;
	}
}

package net.wchbdotnet.arcaneward;

import net.runelite.api.ItemComposition;

final class ItemAppearanceSnapshot
{
	private final ItemComposition item;
	private final int inventoryModel;
	private final short[] colorToReplace;
	private final short[] colorToReplaceWith;
	private final short[] textureToReplace;
	private final short[] textureToReplaceWith;
	private final int xan2d;
	private final int yan2d;
	private final int zan2d;

	ItemAppearanceSnapshot(ItemComposition item)
	{
		this.item = item;
		inventoryModel = item.getInventoryModel();
		colorToReplace = clone(item.getColorToReplace());
		colorToReplaceWith = clone(item.getColorToReplaceWith());
		textureToReplace = clone(item.getTextureToReplace());
		textureToReplaceWith = clone(item.getTextureToReplaceWith());
		xan2d = item.getXan2d();
		yan2d = item.getYan2d();
		zan2d = item.getZan2d();
	}

	void restore()
	{
		item.setInventoryModel(inventoryModel);
		item.setColorToReplace(clone(colorToReplace));
		item.setColorToReplaceWith(clone(colorToReplaceWith));
		item.setTextureToReplace(clone(textureToReplace));
		item.setTextureToReplaceWith(clone(textureToReplaceWith));
		item.setXan2d(xan2d);
		item.setYan2d(yan2d);
		item.setZan2d(zan2d);
	}

	private static short[] clone(short[] value)
	{
		return value == null ? null : value.clone();
	}
}

package net.wchbdotnet.arcaneward;

public enum ShieldAppearance
{
	ELIDINIS("Original ward"),
	ARCANE_BASE("Arcane spirit shield"),
	ARCANE_OR("Arcane spirit shield (or)"),
	ARCANE_F("Arcane spirit shield (f)");

	private final String label;

	ShieldAppearance(String label)
	{
		this.label = label;
	}

	ShieldAppearance next()
	{
		ShieldAppearance[] appearances = values();
		return appearances[(ordinal() + 1) % appearances.length];
	}

	boolean usesArcaneModel()
	{
		return this != ELIDINIS;
	}

	boolean isRecoloredArcane()
	{
		return this == ARCANE_OR || this == ARCANE_F;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

